{
  "version": 1,
  "state": [
    {
      "id": "done",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"done\""
        ]
      },
      "label": "Compile succeeded; its source-tagged result is retained"
    },
    {
      "id": "error",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"error\""
        ]
      },
      "label": "Compile failed"
    },
    {
      "id": "timeout",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"timeout\""
        ]
      },
      "label": "Compile timed out"
    },
    {
      "id": "released",
      "when": {
        "all": [
          {
            "eq": [
              {
                "var": "status"
              },
              "\"compiling\""
            ]
          },
          {
            "eq": [
              {
                "var": "timeoutRef"
              },
              "0"
            ]
          }
        ]
      },
      "label": "Compilation state retained after resources were released"
    },
    {
      "id": "compiling",
      "when": {
        "eq": [
          {
            "var": "status"
          },
          "\"compiling\""
        ]
      },
      "label": "Latest compile owns the worker and deadline"
    },
    {
      "id": "idle",
      "when": true,
      "label": "Idle"
    }
  ],
  "step": [
    {
      "id": "stutter",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Quiesce"
        ]
      },
      "label": "No further public call"
    },
    {
      "id": "start",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"compile\""
        ]
      },
      "label": "Start a fresh compile after terminating prior work"
    },
    {
      "id": "cancel",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"cancel\""
        ]
      },
      "label": "Cancel and invalidate prior callbacks"
    },
    {
      "id": "cleanup",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"cleanup\""
        ]
      },
      "label": "Run React effect cleanup"
    },
    {
      "id": "constructor",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"constructorThrow\""
        ]
      },
      "label": "Worker construction throws"
    },
    {
      "id": "post",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"postThrow\""
        ]
      },
      "label": "Posting compile input throws"
    },
    {
      "id": "stale",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"stale\""
        ]
      },
      "label": "Ignore a callback from a replaced job"
    },
    {
      "id": "mismatch",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"mismatch\""
        ]
      },
      "label": "Ignore a message with the wrong job ID"
    },
    {
      "id": "duplicate",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"duplicate\""
        ]
      },
      "label": "Ignore a callback after the job has ended"
    },
    {
      "id": "done",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"done\""
        ]
      },
      "label": "Apply a successful result and release resources"
    },
    {
      "id": "compileError",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"compileError\""
        ]
      },
      "label": "Apply a compiler-reported error and release resources"
    },
    {
      "id": "environmentError",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"environmentError\""
        ]
      },
      "label": "Apply an environment failure reported by the worker"
    },
    {
      "id": "workerError",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"workerError\""
        ]
      },
      "label": "Apply a worker error and release resources"
    },
    {
      "id": "timeout",
      "when": {
        "eq": [
          {
            "to": "lastEvent"
          },
          "\"timeout\""
        ]
      },
      "label": "Apply the deadline and release resources"
    },
    {
      "id": "other",
      "when": true,
      "label": "Observe the hook"
    }
  ]
}

